import functools


def reintentar(n):
    def decorador(func):
        @functools.wraps(func)
        def envoltura(*args, **kwargs):
            ultima = None
            for _ in range(n):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    ultima = e
            raise ultima

        return envoltura

    return decorador

from itertools import islice


def leer_en_lotes(iterable, n):
    if n < 1:
        raise ValueError("n debe ser >= 1")
    it = iter(iterable)
    while True:
        lote = list(islice(it, n))
        if not lote:
            return
        yield lote

