from collections import deque


class UltimosN:
    def __init__(self, n):
        self._datos = deque(maxlen=n)

    def agregar(self, x):
        self._datos.append(x)

    def valores(self):
        return list(self._datos)

    def promedio(self):
        if not self._datos:
            return None
        return sum(self._datos) / len(self._datos)


def rotar(lista, k):
    d = deque(lista)
    d.rotate(k)
    return list(d)

